+	chain_settings[p_index]->root_bone.name = p_bone_name;
+	Skeleton3D *sk = get_skeleton();
+	if (sk) {
+		set_root_bone(p_index, sk->find_bone(chain_settings[p_index]->root_bone.name));
+	}
