+	}
+}
+
+void TwoBoneIK3D::_init_joints(Skeleton3D *p_skeleton, int p_index) {
+	TwoBoneIK3DSetting *setting = tb_settings[p_index];
+	cached_space = p_skeleton->get_global_transform_interpolated();
+	if (!setting->simulation_dirty) {
+		return;
+	}
