+		~IterateIK3DSetting() {
+			for (uint32_t i = 0; i < joint_settings.size(); i++) {
+				if (joint_settings[i]) {
+					memdelete(joint_settings[i]);
+				}
+			}
+			joint_settings.clear();
+		}
+	};
